<?php $title='Products';require 'includes/header.php';$products=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-4"><h1>Products</h1><a class="btn btn-primary" href="add-product.php">Add Product</a></div><div class="table-responsive bg-white rounded-4 shadow-sm"><table class="table align-middle"><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Featured</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><img class="thumb" src="<?=e($p['image'])?>"></td><td><?=e($p['product_name'])?></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?=$p['featured']?'Yes':'No'?></td><td><a class="btn btn-sm btn-outline-primary" href="edit-product.php?id=<?=$p['id']?>">Edit</a> <a onclick="return confirm('Delete this product?')" class="btn btn-sm btn-outline-danger" href="delete-product.php?id=<?=$p['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>